 * The instant-runoff count itself, given a validated election.
 */

function resolveTie(tiedNames, history) {
  let candidates = tiedNames.slice()
  while (true) {
    let foundRound = -1
    for (let r = 0; r < history.length; r++) {
      const vals = candidates.map((c) => history[r].get(c))
      if (!vals.every((v) => v === vals[0])) {
        foundRound = r
        break
      }
    }
    if (foundRound === -1) {
      candidates.sort()
      return candidates[candidates.length - 1]
    }
    const vals = candidates.map((c) => history[foundRound].get(c))
    const min = Math.min(...vals)
    candidates = candidates.filter((c) => history[foundRound].get(c) === min)
    if (candidates.length === 1) return candidates[0]
  }
}

export function runElection(candidates, ballots) {
  const continuing = new Set(candidates)
  const history = []
  const rounds = []
  let winner = null
  const totalBallots = ballots.reduce((s, b) => s + b.count, 0)

  while (true) {
    const votes = new Map()
    for (const c of continuing) votes.set(c, 0)
    for (const b of ballots) {
      const pick = b.names.find((n) => continuing.has(n))
      if (pick !== undefined) votes.set(pick, votes.get(pick) + b.count)
    }
    const activeTotal = [...votes.values()].reduce((a, b) => a + b, 0)
    const exhausted = totalBallots - activeTotal
    history.push(votes)

    if (activeTotal === 0) {
      rounds.push({ votes, exhausted, eliminated: null })
      break
    }

    let roundWinner = null
    for (const c of continuing) {
      if (votes.get(c) * 2 > activeTotal) {
        roundWinner = c
        break
      }
    }
    if (roundWinner !== null) {
      rounds.push({ votes, exhausted, eliminated: null })
      winner = roundWinner
      break
    }

    let min = Infinity
    for (const c of continuing) {
      const v = votes.get(c)
      if (v < min) min = v
    }
    const tied = [...continuing].filter((c) => votes.get(c) === min)
    const toEliminate = tied.length === 1 ? tied[0] : resolveTie(tied, history)

    rounds.push({ votes, exhausted, eliminated: toEliminate })
    continuing.delete(toEliminate)
  }

  return { rounds, winner }
}
"}

