/**
 * The command. `node src/cli.js rounds` prints every round of the instant-runoff
 * count read from standard input, and `node src/cli.js tally` prints only how
 * many rounds ran and who won.
 */

import { readFileSync } from 'node:fs'
import { parseElection, ParseError } from './parse.js'
import { runElection } from './count.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function formatVotes(votes) {
  const entries = [...votes.entries()]
  entries.sort((a, b) => {
    if (b[1] !== a[1]) return b[1] - a[1]
    return a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0
  })
  return entries.map(([name, count]) => `${name}=${count}`).join(' ')
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'rounds' && args[0] !== 'tally')) {
    fail('usage: cli.js rounds|tally')
    return
  }
  const mode = args[0]

  const input = readFileSync(0, 'utf8')

  let election
  try {
    election = parseElection(input)
  } catch (err) {
    if (err instanceof ParseError) {
      if (err.line === null || err.line === undefined) {
        fail(err.message)
      } else {
        fail(`line ${err.line}: ${err.message}`)
      }
      return
    }
    throw err
  }

  const { rounds, winner } = runElection(election.candidates, election.ballots)

  const out = []
  if (mode === 'rounds') {
    rounds.forEach((round, i) => {
      out.push(`round ${i + 1}: ${formatVotes(round.votes)} exhausted=${round.exhausted}`)
      if (round.eliminated !== null) {
        out.push(`eliminated ${round.eliminated}`)
      }
    })
  } else {
    out.push(`rounds ${rounds.length}`)
  }
  out.push(winner !== null ? `winner ${winner}` : 'no winner')

  process.stdout.write(out.join('\n') + '\n')
}

main()
